import{_ as a,a0 as l,w as i,s,ao as u,I as e,x as p,a1 as o,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"使用 utmpdump 監控 CentOS 用户登錄歷史 | LCTT x X-CMD","titleTemplate":false,"description":"使用 utmpdump 監控 CentOS 用户登錄歷史 | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 utmpdump 監控 CentOS 用户登錄歷史 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 utmpdump 監控 CentOS 用户登錄歷史 | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20140926 How to monitor user login history on CentOS with utmpdump","title":"使用 utmpdump 監控 CentOS 用户登錄歷史","tag":"201411","desc":""},"relativePath":"201411/20140926 How to monitor user login history on CentOS with utmpdump.md","filePath":"[post].md"}'),n={name:"201411/20140926 How to monitor user login history on CentOS with utmpdump.md"};function d(g,t,c,f,T,_){const m=l("Link");return i(),s("div",null,[t[16]||(t[16]=u(`<h1 id="使用-utmpdump-監控-centos-用户登錄歷史" tabindex="-1">使用 utmpdump 監控 CentOS 用户登錄歷史 <a class="header-anchor" href="#使用-utmpdump-監控-centos-用户登錄歷史" aria-label="Permalink to “使用 utmpdump 監控 CentOS 用户登錄歷史”">​</a></h1><p>保留、維護和分析日誌（如某個特定時期內發生過的，或正在發生的帳號事件），是Linux系統管理員最基礎和最重要的任務之一。對於用户管理，檢查用户的登入和登出日誌（不管是失敗的，還是成功的）可以讓我們對任何潛在的安全隱患或未經授權使用系統的情況保持警惕。例如，工作時間之外或放假期間的來自未知IP地址或帳號的遠程登錄應當發出紅色警報。</p><p>在CentOS系統上，用户登錄歷史存儲在以下這些文件中：</p><ul><li>/var/run/utmp（用於記錄當前打開的會話）被who和w工具用來記錄當前有誰登錄以及他們正在做什麼，而uptime用來記錄系統啓動時間。</li><li>/var/log/wtmp （用於存儲系統連接歷史記錄）被last工具用來記錄最後登錄的用户的列表。</li><li>/var/log/btmp（記錄失敗的登錄嘗試）被lastb工具用來記錄最後失敗的登錄嘗試的列表。</li></ul><p><img src="https://farm4.staticflickr.com/3871/15106743340_bd13fcfe1c_o.png" alt=""></p><p>在本文中，我將介紹如何使用utmpdump，這個小程序來自sysvinit-tools包，可以用於轉儲二進制日誌文件到文本格式的文件以便檢查。此工具默認在CentOS 6和7系列上可用。utmpdump收集到的信息比先前提到過的工具的輸出要更全面，這讓它成為一個勝任該工作的很不錯的工具。除此之外，utmpdump可以用於修改utmp或wtmp。如果你想要修復二進制日誌中的任何損壞條目，它會很有用（LCTT 譯註：我怎麼覺得這像是做壞事的前奏？）。</p><h3 id="utmpdump的使用及其輸出説明" tabindex="-1">Utmpdump的使用及其輸出説明 <a class="header-anchor" href="#utmpdump的使用及其輸出説明" aria-label="Permalink to “Utmpdump的使用及其輸出説明”">​</a></h3><p>正如我們之前提到的，這些日誌文件，與我們大多數人熟悉的其它日誌相比（如/var/log/messages，/var/log/cron，/var/log/maillog），是以二進制格式存儲的，因而我們不能使用像less或more這樣的文件命令來查看它們的內容。所以，utmpdump的出現拯救了世界。</p><p>為了要顯示/var/run/utmp的內容，請運行以下命令：</p><pre><code># utmpdump /var/run/utmp 
</code></pre><p><img src="https://farm6.staticflickr.com/5595/15106696599_60134e3488_z.jpg" alt=""></p><p>同樣要顯示/var/log/wtmp的內容：</p><pre><code># utmpdump /var/log/wtmp 
</code></pre><p><img src="https://farm6.staticflickr.com/5591/15106868718_6321c6ff11_z.jpg" alt=""></p><p>最後，對於/var/log/btmp：</p><pre><code># utmpdump /var/log/btmp 
</code></pre><p><img src="https://farm6.staticflickr.com/5562/15293066352_c40bc98ca4_z.jpg" alt=""></p><p>正如你所能看到的，三種情況下的輸出結果是一樣的，除了utmp和btmp的記錄是按時間排序，而wtmp的順序是顛倒的這個原因外（LCTT 譯註：此處原文有誤，實際上都是按照時間順序排列的）。</p><p>每個日誌行格式化成了多列，説明如下。第一個字段顯示了會話識別符，而第二個字段則是PID。第三個字段可以是以下值：--（表示運行等級改變或系統重啓），bw（啓動守候進程），數字（表示TTY編號），或者字符和數字（表示偽終端）。第四個字段可以為空或用户名、重啓或運行級別。第五個字段是主TTY或PTY（偽終端），如果此信息可獲得的話。第六個字段是遠程主機名（如果是本地登錄，該字段為空，運行級別信息除外，它會返回內核版本）。第七個字段是遠程系統的IP地址（如果是本地登錄，該字段為0.0.0.0）。如果沒有提供DNS解析，第六和第七字段會顯示相同的信息（遠程系統的IP地址）。最後一個（第八）字段指明瞭該記錄創建的日期和時間。</p><h3 id="utmpdump使用樣例" tabindex="-1">Utmpdump使用樣例 <a class="header-anchor" href="#utmpdump使用樣例" aria-label="Permalink to “Utmpdump使用樣例”">​</a></h3><p>下面提供了一些utmpdump的簡單使用情況。</p><p>1、 檢查8月18日到9月17日之間某個特定用户（如gacanepa）的登錄次數。</p><pre><code># utmpdump /var/log/wtmp | grep gacanepa 
</code></pre><p><img src="https://farm4.staticflickr.com/3857/15293066362_fb2dd566df_z.jpg" alt=""></p>`,24)),e("p",null,[t[1]||(t[1]=p("如果你需要回顧先前日期的登錄信息，你可以檢查/var/log下的wtmp-YYYYMMDD（或wtmp.[1...N]）和btmp-YYYYMMDD（或btmp.[1...N]）文件，這些是由",-1)),o(m,{href:"http://linux.cn/article-4126-1.html"},{default:r(()=>[...t[0]||(t[0]=[p("logrotate",-1)])]),_:1}),t[2]||(t[2]=p("生成的舊wtmp和btmp的歸檔文件。",-1))]),t[17]||(t[17]=u(`<p>2、 統計來自IP地址192.168.0.101的登錄次數。</p><pre><code># utmpdump /var/log/wtmp | grep 192.168.0.101 
</code></pre><p><img src="https://farm4.staticflickr.com/3842/15106743480_55ce84c9fd_z.jpg" alt=""></p><p>3、 顯示失敗的登錄嘗試。</p><pre><code># utmpdump /var/log/btmp 
</code></pre><p><img src="https://farm4.staticflickr.com/3858/15293065292_e1d2562206_z.jpg" alt=""></p><p>在/var/log/btmp輸出中，每個日誌行都與一個失敗的登錄嘗試相關（如使用不正確的密碼，或者一個不存在的用户ID）。上面圖片中高亮部分顯示了使用不存在的用户ID登錄，這警告你有人嘗試猜測常用帳號名來闖入系統。這在使用tty1的情況下是個極其嚴重的問題，因為這意味着某人對你機器上的終端具有訪問權限（該檢查一下誰拿到了進入你數據中心的鑰匙了，也許吧？）</p><p>4、 顯示每個用户會話的登入和登出信息</p><pre><code># utmpdump /var/log/wtmp 
</code></pre><p><img src="https://farm4.staticflickr.com/3835/15293065312_c762360791_z.jpg" alt=""></p><p>在/var/logwtmp中，一次新的登錄事件的特徵是，第一個字段為‘7’，第三個字段是一個終端編號（或偽終端id），第四個字段為用户名。相關的登出事件會在第一個字段顯示‘8’，第二個字段顯示與登錄一樣的PID，而終端編號字段空白。例如，仔細觀察上面圖片中PID 1463的行。</p><ul><li>在 [Fri Sep 19 11:57:40 2014 ART]，TTY1上顯示登錄提示符。</li><li>在 [Fri Sep 19 12:04:21 2014 ART]，用户 root 登入。</li><li>在 [Fri Sep 19 12:07:24 2014 ART]，用户 root 登出。</li></ul><p>旁註：第四個字段的LOGIN意味着出現了一次登錄到第五字段指定的終端的提示。</p><p>到目前為止，我介紹一些有點瑣碎的例子。你可以將utmpdump和其它一些文本處理工具，如awk、sed、grep或cut組合，來產生過濾和加強的輸出。</p><p>例如，你可以使用以下命令來列出某個特定用户（如gacanepa）的所有登錄事件，併發送輸出結果到.csv文件，它可以用像LibreOffice Calc或Microsoft Excel之類的文字或工作簿應用程序打開查看。讓我們只顯示PID、用户名、IP地址和時間戳：</p><pre><code> # utmpdump /var/log/wtmp | grep -E &quot;\\[7].*gacanepa&quot; | awk -v OFS=&quot;,&quot; &#39;BEGIN {FS=&quot;] &quot;}; {print $2,$4,$7,$8}&#39; | sed -e &#39;s/\\[//g&#39; -e &#39;s/\\]//g&#39; 
</code></pre><p><img src="https://farm4.staticflickr.com/3851/15293065352_91e1c1e4b6_z.jpg" alt=""></p><p>就像上面圖片中三個高亮區域描繪的那樣，過濾邏輯操作是由三個管道步驟組成的。第一步用於查找由用户gacanepa觸發的登錄事件（[7]）；第二步和第三部用於選擇期望的字段，移除utmpdump輸出的方括號並設置輸出字段分隔符為逗號。</p><p>當然，如果你想要在以後打開來看，你需要重定向上面的命令輸出到文件（添加“&gt;[文件名].csv”到命令後面）。</p><p><img src="https://farm4.staticflickr.com/3889/15106867768_0e37881a25_z.jpg" alt=""></p><p>在更為複雜的例子中，如果你想要知道在特定時間內哪些用户（在/etc/passwd中列出）沒有登錄，你可以從/etc/passwd中提取用户名，然後運行grep命令來獲取/var/log/wtmp輸出中對應用户的列表。就像你看到的那樣，有着無限可能。</p><p>在進行總結之前，讓我們簡要地展示一下utmpdump的另外一種使用情況：修改utmp或wtmp。由於這些都是二進制日誌文件，你不能像編輯文件一樣來編輯它們。取而代之是，你可以將其內容輸出成為文本格式，並修改文本輸出內容，然後將修改後的內容導入回二進制日誌中。如下：</p><pre><code># utmpdump /var/log/utmp &gt; tmp_output
&lt;使用文本編輯器修改 tmp_output&gt;
# utmpdump -r tmp_output &gt; /var/log/utmp 
</code></pre><p>這在你想要移除或修復二進制日誌中的任何偽造條目時很有用。</p><p>下面小結一下，utmpdump從utmp、wtmp和btmp日誌文件或輪循的舊歸檔文件來讀取詳細的登錄事件，來補充如who，w，uptime，last，lastb之類的標準工具的不足，這也使得它成為一個很棒的工具。</p><p>你可以隨意添加評論以加強本帖的含金量。</p><hr>`,27)),e("p",null,[t[4]||(t[4]=p("via: ",-1)),o(m,{href:"http://xmodulo.com/2014/09/monitor-user-login-history-centos-utmpdump.html"},{default:r(()=>[...t[3]||(t[3]=[p("http://xmodulo.com/2014/09/monitor-user-login-history-centos-utmpdump.html",-1)])]),_:1})]),e("p",null,[t[8]||(t[8]=p("作者：",-1)),o(m,{href:"http://xmodulo.com/author/gabriel"},{default:r(()=>[...t[5]||(t[5]=[p("Gabriel Cánepa",-1)])]),_:1}),t[9]||(t[9]=p(" 譯者：",-1)),o(m,{href:"https://github.com/GOLinux"},{default:r(()=>[...t[6]||(t[6]=[p("GOLinux",-1)])]),_:1}),t[10]||(t[10]=p(" 校對：",-1)),o(m,{href:"https://github.com/wxy"},{default:r(()=>[...t[7]||(t[7]=[p("wxy",-1)])]),_:1})]),e("p",null,[t[13]||(t[13]=p("本文由 ",-1)),o(m,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[11]||(t[11]=[p("LCTT",-1)])]),_:1}),t[14]||(t[14]=p(" 原創翻譯，",-1)),o(m,{href:"http://linux.cn/"},{default:r(()=>[...t[12]||(t[12]=[p("Linux中國",-1)])]),_:1}),t[15]||(t[15]=p(" 榮譽推出",-1))])])}const h=a(n,[["render",d]]);export{v as __pageData,h as default};
